EXPECTED = {'bot/handlers/user/keys.py': 'd64c8f13651092bc92820568ee75d5908eeebf336c323245df208cdc80a7aa68', 'bot/utils/key_sender.py': 'b96933b7e00e232559215c006a1b2d903f0329f78677d4487616fa36de7d2e35', 'bot/utils/text.py': 'd3cab4c3f6e778231885d61fc29f5815d63a57dcffe36ccb51aa1bb402016b6d'}
files = sorted({e[0] for e in EDITS})
for f in files:
    shutil.copy2(f, f + ".bak")
try:
    for f in files:
        s = open(f, encoding="utf-8").read()
        for ef, old, new in EDITS:
            if ef != f:
                continue
            if s.count(old) != 1:
                raise RuntimeError(f"{f}: фрагмент найден {s.count(old)} раз(а), ожидался 1")
            s = s.replace(old, new, 1)
        open(f, "w", encoding="utf-8").write(s)
        h = hashlib.sha256(s.encode("utf-8")).hexdigest()
        if h != EXPECTED[f]:
            raise RuntimeError(f"{f}: SHA256 не совпал ({h})")
except Exception as e:
    for f in files:
        shutil.move(f + ".bak", f)
    print("ОШИБКА, всё откачено:", e)
    sys.exit(1)
print("OK: патч применён, бэкапы *.bak рядом с файлами")
